package me.nimnakse.water_management.utility_bills.controller;
import jakarta.validation.Valid; import java.util.List; import me.nimnakse.water_management.common.api.ApiResponse; import me.nimnakse.water_management.utility_bills.dto.request.UtilityBillCalculatorReq; import me.nimnakse.water_management.utility_bills.dto.request.UtilityBillGenerateReq; import me.nimnakse.water_management.utility_bills.dto.request.UtilityBillMeterReadReq; import me.nimnakse.water_management.utility_bills.dto.response.UtilityBillCalculatorRes; import me.nimnakse.water_management.utility_bills.dto.response.UtilityBillRes; import me.nimnakse.water_management.utility_bills.dto.response.UtilityBillZoneSummaryRes; import me.nimnakse.water_management.utility_bills.service.UtilityBillService; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/utility-bills") public class UtilityBillController { private final UtilityBillService service; public UtilityBillController(UtilityBillService service){this.service=service;} @GetMapping("/zones/summary") public ResponseEntity<ApiResponse<List<UtilityBillZoneSummaryRes>>> zoneSummaries(@RequestParam(required=false) Long orgUnitId,@RequestParam(required=false) List<Long> billingZoneIds){ return ResponseEntity.ok(ApiResponse.success(service.listZoneSummaries(orgUnitId,billingZoneIds))); } @PostMapping("/generate") public ResponseEntity<ApiResponse<List<UtilityBillRes>>> generate(@Valid @RequestBody UtilityBillGenerateReq request){ return ResponseEntity.ok(ApiResponse.success(service.generate(request))); } @GetMapping("/open") public ResponseEntity<ApiResponse<List<UtilityBillRes>>> open(@RequestParam(required=false) Long orgUnitId,@RequestParam(required=false) Long billingZoneId){ return ResponseEntity.ok(ApiResponse.success(service.listOpen(orgUnitId,billingZoneId))); } @GetMapping("/closed") public ResponseEntity<ApiResponse<List<UtilityBillRes>>> closed(@RequestParam(required=false) Long orgUnitId,@RequestParam(required=false) Long billingZoneId){ return ResponseEntity.ok(ApiResponse.success(service.listClosed(orgUnitId,billingZoneId))); } @PostMapping("/{billId}/read") public ResponseEntity<ApiResponse<UtilityBillRes>> meterRead(@PathVariable Long billId,@Valid @RequestBody UtilityBillMeterReadReq request){ return ResponseEntity.ok(ApiResponse.success(service.meterRead(billId,request))); } @PostMapping("/{billId}/reopen") public ResponseEntity<ApiResponse<UtilityBillRes>> reopen(@PathVariable Long billId){ return ResponseEntity.ok(ApiResponse.success(service.reopen(billId))); } @PostMapping("/calculate") public ResponseEntity<ApiResponse<UtilityBillCalculatorRes>> calculate(@Valid @RequestBody UtilityBillCalculatorReq request){ return ResponseEntity.ok(ApiResponse.success(service.calculate(request))); } }